import OpenAI from 'openai';
const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

export async function analyzeSpec(spec: string) {
  const res = await openai.responses.create({
    model: 'o3-mini',
    reasoning: { effort: 'low' },
    instructions: 'Você é um arquiteto de sistemas distribuídos. Aponte gargalos.',
    input: spec,
    max_output_tokens: 300,
  });
  return {
    text: res.output_text,
    reasoningTokens: res.usage?.output_tokens_details?.reasoning_tokens ?? 0,
  };
}

import fs from 'node:fs';
import OpenAI from 'openai';
const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

export async function dispatchOpenAIBatch(jsonlPath: string) {
  const file = await openai.files.create({
    file: fs.createReadStream(jsonlPath),
    purpose: 'assistants',
  });
  return openai.batches.create({
    input_file_id: file.id,
    endpoint: '/v1/responses',
    completion_window: '1h',
  });
}

import Anthropic from '@anthropic-ai/sdk';
const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });

export async function reviewDiff(guidelines: string, diff: string) {
  const response = await anthropic.messages.create({
    model: 'claude-3-7-sonnet-20250219',
    max_tokens: 4096,
    temperature: 0.2,
    thinking: { type: 'enabled', budget_tokens: 4096 },
    system: [{ type: 'text', text: guidelines, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: diff }],
  });
  return response.content[0].type === 'text' ? response.content[0].text : '';
}

