import { InferenceClient } from '@huggingface/inference';

const hf = new InferenceClient(process.env.HF_TOKEN);

export async function runPipeline(text: string, imageBlob: Blob) {
  const chat = await hf.chatCompletion({
    model: 'meta-llama/Llama-3.3-70B-Instruct',
    provider: 'groq',
    messages: [{ role: 'user', content: text }],
    max_tokens: 1024,
  });
  const embedding = await hf.featureExtraction({ model: 'BAAI/bge-large-en-v1.5', inputs: text });
  const caption = await hf.imageToText({ model: 'Salesforce/blip-image-captioning-large', data: imageBlob });
  const speechBlob = await hf.textToSpeech({ model: 'espnet/kan-bayashi_ljspeech_vits', inputs: text });
  return { reply: chat.choices[0]?.message?.content ?? '', embedding, caption: caption.generated_text, speechBlob };
}

export interface FinOpsInput {
  newInputTokens: number;
  cachedInputTokens: number;
  thinkingTokens: number;
  outputTokens: number;
  priceInPerMillionUsd: number;
  priceCachePerMillionUsd: number;
  priceOutPerMillionUsd: number;
  isBatch24h: boolean;
}

export function estimateRequestCostUsd(x: FinOpsInput): number {
  const batchFactor = x.isBatch24h ? 0.5 : 1.0;
  const inputUsd = (x.newInputTokens * x.priceInPerMillionUsd) / 1_000_000;
  const cacheUsd = (x.cachedInputTokens * x.priceCachePerMillionUsd) / 1_000_000;
  const outputUsd = (x.outputTokens * x.priceOutPerMillionUsd) / 1_000_000;
  return (inputUsd + cacheUsd + outputUsd) * batchFactor;
}

export function shouldUseDedicatedGpu(reqPerHour: number, costPerReqUsd: number, gpuHourlyUsd: number): boolean {
  return reqPerHour * costPerReqUsd > gpuHourlyUsd;
}

